   * Resolves the flight model context for an entity: the regime determines
   * the planet's context (atmospheric density, O(1) chunk-cached terrain,
   * pads). Entities in space get no planet context whatsoever.
   */
  private resolveRegimeCtx(entity: SimEntity): { planet?: PlanetAtmo; options: FlightOptions } {
    // TASK-85: Cruise rules are defined in the SHARED integrator — the
    // server tick passes the same clearance the client predictor uses
    // (cruiseAllowedAt against the system's regime planets), so a player's
    // ship only boosts at distances 1.5 km or more outside any atmospheric
    // boundary. AI ships never reach these options (they integrate without
    // options, with boost 0).
    const cruiseAllowed = cruiseAllowedAt(entity.ship.pos, this.regimePlanets);
    const empty = {
      planet: undefined as PlanetAtmo | undefined,
      options: { heightAt: () => 0, pads: [], cruiseAllowed },
    };
    if (entity.ship.regime === 'space' || !entity.planetId) return empty;
    const planet = this.system.planets.find((p) => p.id === entity.planetId);
    if (!planet) return empty;
    const ctx = this.getTerrain(planet.id);
    ctx.update(entity.ship.pos.x, entity.ship.pos.z);
    return {
      planet: planet.hasAtmosphere
        ? {
            atmosphereDensity: planetAtmosphereDensity(planet),
            atmosphereRadius: planetAtmosphereRadius(planet),
